              "field": "Stage Minutes",
              "type": "quantitative",
              "stack": true
            },
            "order": {
              "field": "ord",
              "type": "quantitative"
            },
            "color": {
              "field": "Step",
              "type": "nominal",
              "scale": {
                "domain": [
                  "Preparation",
                  "Validation",
                  "Formatting",
